module table_sort_check(\n    input clk,\n    input rst_n,\n    input start,\n    input [255:0] table_in,\n    output reg result,\n    output reg done\n);\n    \n    // Parameters\n    localparam N = 4;\n    localparam M = 4;\n    localparam DATA_WIDTH = 4;\n    \n    // State definitions\n    localparam [3:0] \n        IDLE         = 4'd0,\n        UNPACK       = 4'd1,\n        INIT_SW_IDX  = 4'd2,\n        EVAL_SWAP    = 4'd3,\n        ROW_INIT     = 4'd4,\n        ROW_INIT_ROW = 4'd5,\n        CHECK_COL    = 4'd6,\n        ROW_DECIDE   = 4'd7,\n        NEXT_ROW     = 4'd8,\n        NEXT_SW_IDX  = 4'd9,\n        SET_RESULT   = 4'd10,\n        DONE         = 4'd11;\n    \n    // Internal registers\n    reg [DATA_WIDTH-1:0] original_table [0:N-1][0:M-1];\n    reg [DATA_WIDTH-1:0] current_table [0:N-1][0:M-1];\n    reg [3:0] state, next_state;\n    reg [2:0] sw_idx;\n    reg [1:0] row_cnt, col_cnt;\n    reg [2:0] mismatch_count;\n    reg all_rows_ok;\n    reg possible;\n    reg [1:0] col1, col2;\n    integer i, j;\n    \n    // FSM update\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 0;\n            done <= 0;\n            for (i = 0; i < N; i = i+1) begin\n                for (j = 0; j < M; j = j+1) begin\n                    original_table[i][j] <= 4'd0;\n                    current_table[i][j] <= 4'd0;\n                end\n            end\n            sw_idx <= 3'd0;\n            row_cnt <= 2'd0;\n            col_cnt <= 2'd0;\n            mismatch_count <= 3'd0;\n            all_rows_ok <= 1'b0;\n            possible <= 1'b0;\n            col1 <= 2'd0;\n            col2 <= 2'd0;\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) next_state = UNPACK;\n                end\n                \n                UNPACK: begin\n                    for (i = 0; i < N; i = i+1) begin\n                        for (j = 0; j < M; j = j+1) begin\n                            original_table[i][j] <= table_in[((i*M)+j)*DATA_WIDTH +: DATA_WIDTH];\n                        end\n                    end\n                    next_state = INIT_SW_IDX;\n                end\n                \n                INIT_SW_IDX: begin\n                    sw_idx <= 3'd0;\n                    possible <= 1'b0;\n                    all_rows_ok <= 1'b1;\n                    next_state = EVAL_SWAP;\n                end\n                \n                EVAL_SWAP: begin\n                    col1 <= 2'd0;\n                    col2 <= 2'd0;\n                    if (sw_idx == 3'd0) begin\n                        for (i = 0; i < N; i = i+1) begin\n                            for (j = 0; j < M; j = j+1) begin\n                                current_table[i][j] <= original_table[i][j];\n                            end\n                        end\n                    end else begin\n                        case (sw_idx)\n                            3'd1: begin col1 <= 2'd0; col2 <= 2'd1; end\n                            3'd2: begin col1 <= 2'd0; col2 <= 2'd2; end\n                            3'd3: begin col1 <= 2'd0; col2 <= 2'd3; end\n                            3'd4: begin col1 <= 2'd1; col2 <= 2'd2; end\n                            3'd5: begin col1 <= 2'd1; col2 <= 2'd3; end\n                            3'd6: begin col1 <= 2'd2; col2 <= 2'd3; end\n                            default: begin\n                                col1 <= 2'd0;\n                                col2 <= 2'd0;\n                            end\n                        endcase\n                        for (i = 0; i < N; i = i+1) begin\n                            for (j = 0; j < M; j = j+1) begin\n                                if (j == col1) current_table[i][j] <= original_table[i][col2];\n                                else if (j == col2) current_table[i][j] <= original_table[i][col1];\n                                else current_table[i][j] <= original_table[i][j];\n                            end\n                        end\n                    end\n                    row_cnt <= 2'd0;\n                    next_state = ROW_INIT;\n                end\n                \n                ROW_INIT: begin\n                    next_state = ROW_INIT_ROW;\n                end\n                \n                ROW_INIT_ROW: begin\n                    col_cnt <= 2'd0;\n                    mismatch_count <= 3'd0;\n                    next_state = CHECK_COL;\n                end\n                \n                CHECK_COL: begin\n                    if (current_table[row_cnt][col_cnt] != (col_cnt + 4'd1))\n                        mismatch_count <= mismatch_count + 3'd1;\n                    col_cnt <= col_cnt + 2'd1;\n                    next_state = (col_cnt < (M-1)) ? CHECK_COL : ROW_DECIDE;\n                end\n                \n                ROW_DECIDE: begin\n                    if (mismatch_count != 3'd0 && mismatch_count != 3'd2)\n                        all_rows_ok <= 1'b0;\n                    next_state = NEXT_ROW;\n                end\n                \n                NEXT_ROW: begin\n                    row_cnt <= row_cnt + 2'd1;\n                    if (row_cnt == (N-1)) begin\n                        if (all_rows_ok)\n                            possible <= 1'b1;\n                        next_state = NEXT_SW_IDX;\n                    end else begin\n                        next_state = ROW_INIT_ROW;\n                    end\n                end\n                \n                NEXT_SW_IDX: begin\n                    sw_idx <= sw_idx + 3'd1;\n                    if (sw_idx < 3'd6) begin\n                        all_rows_ok <= 1'b1;\n                        next_state = EVAL_SWAP;\n                    end else begin\n                        next_state = SET_RESULT;\n                    end\n                end\n                \n                SET_RESULT: begin\n                    result <= possible;\n                    next_state = DONE;\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    next_state = IDLE;\n                end\n                \n                default: next_state = IDLE;\n            endcase\n        end\n    end\n\nendmodule